import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise OSError("script_path does not exist")

    process = subprocess.Popen(['bash', script_path])
    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    total_cpu = 0.0
    total_mem = 0
    start_time = time.time()

    while process.poll() is None:
        if time.time() - start_time > timeout:
            process.terminate()
            process.wait()
            break
        try:
            cpu = ps_process.cpu_percent(interval=0.1)
            mem = ps_process.memory_info().rss
            total_cpu += cpu
            total_mem += mem
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

    return {'CPU Usage': total_cpu, 'Memory Usage': total_mem}

